// ProcurementServer is the server API for Procurement service.
// All implementations must embed UnimplementedProcurementServer
// for forward compatibility.
//
// Procurement is the internal domain API (vendors and requisitions first;
// PO conversion below; GRNs and invoices arrive with later issues). Reachable
// only inside the backend network; clients go through the gateway.
type ProcurementServer interface {
	// CreateVendor validates and inserts a vendor. The caller's tenant and user
	// come from the auth metadata (x-tenant-id / x-user-id / x-role) injected
	// by the gateway; vendor codes are unique per tenant.
	CreateVendor(context.Context, *CreateVendorRequest) (*Vendor, error)
	// GetVendor returns one vendor of the caller's tenant; other tenants'
	// vendors are indistinguishable from missing ones.
	GetVendor(context.Context, *GetVendorRequest) (*Vendor, error)
	// UpdateVendor mutates mutable fields of an active vendor. Deactivated
	// vendors are immutable (soft-deleted).
	UpdateVendor(context.Context, *UpdateVendorRequest) (*Vendor, error)
	// DeactivateVendor soft-deletes a vendor: it stays readable for history but
	// cannot be used in new purchase orders.
	DeactivateVendor(context.Context, *DeactivateVendorRequest) (*Vendor, error)
	// ListVendors returns one page of the caller's vendors ordered by code.
	// query matches a code prefix or a name substring (case-insensitive);
	// status and query combine. total is the number of matching rows across
	// all pages.
	ListVendors(context.Context, *ListVendorsRequest) (*ListVendorsResponse, error)
	// CreateRequisition creates a draft for the caller (the requester is the
	// caller from the auth metadata). The PR number (PR-%06d) is generated
	// server-side per tenant; total_cents is computed server-side. Items may
	// be empty — a draft collects its lines before submit.
	CreateRequisition(context.Context, *CreateRequisitionRequest) (*Requisition, error)
	// UpdateRequisition replaces the line items of a draft the caller owns
	// (admins may act on any requisition) and recomputes total_cents.
	// Non-draft requisitions are immutable.
	UpdateRequisition(context.Context, *UpdateRequisitionRequest) (*Requisition, error)
	// SubmitRequisition moves a draft the caller owns (admins excepted) to
	// submitted — the basket must hold at least one valid line. The optional
	// idempotency_key (from the gateway's Idempotency-Key header) names the
	// submit: replaying the same key returns the requisition's current state
	// without a second transition; reusing it for another requisition in the
	// tenant is rejected.
	SubmitRequisition(context.Context, *SubmitRequisitionRequest) (*Requisition, error)
	// ListRequisitions returns one page of the caller tenant's requisitions
	// ordered by number descending (newest first). query matches a number
	// prefix (case-insensitive); status and query combine. total is the number
	// of matching rows across all pages. Rows are header-only: items and
	// approval_steps are always empty here — the detail reads own them.
	ListRequisitions(context.Context, *ListRequisitionsRequest) (*ListRequisitionsResponse, error)
	// GetRequisition returns one requisition of the caller's tenant — the
	// detail read that owns the items and approval steps the list rows never
	// carry. Other tenants' requisitions are indistinguishable from missing
	// ones. Read is tenant-wide (requisition:read); ownership applies to edits
	// and submit only.
	GetRequisition(context.Context, *GetRequisitionRequest) (*Requisition, error)
	// DecideApproval applies one approve/reject decision to an approval step.
	// Only the current step (the smallest pending step_no of a submitted
	// requisition) may be decided; the decider must hold the step's
	// role_required (admins excepted) and must not be the requester
	// (self-approval is forbidden for everyone, admins included). A reject
	// skips the remaining steps and rejects the requisition; approving the
	// last step approves it. The optional idempotency_key (from the gateway's
	// Idempotency-Key header) names the decision: replaying the same key on
	// the same step returns the current state without a second decision or a
	// second outbox event; reusing it for another step in the tenant is
	// rejected. The response carries the requisition with its latest
	// approval_steps.
	DecideApproval(context.Context, *DecideApprovalRequest) (*DecideApprovalResponse, error)
	// GetApprovalRules returns the caller tenant's whole rule set.
	GetApprovalRules(context.Context, *GetApprovalRulesRequest) (*ApprovalRulesResponse, error)
	// ReplaceApprovalRules replaces the caller tenant's whole rule set in one
	// transaction (delete + insert). Rules are a live configuration: replacing
	// them never changes steps already materialized on submitted requisitions.
	ReplaceApprovalRules(context.Context, *ReplaceApprovalRulesRequest) (*ApprovalRulesResponse, error)
	// CreatePurchaseOrder converts one approved requisition of the caller's
	// tenant into a draft purchase order (FR-05): lines are copied exactly
	// once, total_cents is recomputed server-side (= the requisition's), and
	// the PO number (PO-%06d) is allocated per tenant inside the conversion
	// transaction — a failed conversion burns no number. vendor_id is
	// required and must name an active vendor of the tenant (requisitions
	// carry no vendor). Idempotent per requisition: converting again returns
	// the existing PO unchanged with created=false (the vendor gate is skipped
	// and a differing vendor_id ignored on replay). On success the
	// requisition closes (approved → closed) and exactly one po.created
	// outbox event commits atomically with the PO. The issue transition,
	// issued_at, and po.issued belong to the lifecycle API (#36).
	CreatePurchaseOrder(context.Context, *CreatePurchaseOrderRequest) (*CreatePurchaseOrderResponse, error)
	// IssuePurchaseOrder moves a draft PO of the caller's tenant to issued and
	// stamps issued_at (FR-06) — the PO leaves the buyer and the
	// acknowledgement SLA clock starts. Anything but draft is rejected
	// (po_illegal_transition); exactly one po.issued outbox event commits with
	// the transition.
	IssuePurchaseOrder(context.Context, *IssuePurchaseOrderRequest) (*PurchaseOrder, error)
	// AcknowledgePurchaseOrder moves an issued PO to acknowledged — the
	// vendor's confirmation (po.acknowledged). Anything but issued is
	// rejected; exactly one po.acknowledged outbox event commits with the
	// transition.
	AcknowledgePurchaseOrder(context.Context, *AcknowledgePurchaseOrderRequest) (*PurchaseOrder, error)
	// CancelPurchaseOrder moves a draft, issued, or acknowledged PO to
	// cancelled — but only while nothing has been received (the total
	// qty_received over all lines is 0); receipts pin the PO and the only exit
	// is close (po_has_receipts). Any other source status is
	// po_illegal_transition; exactly one po.cancelled outbox event commits
	// with the transition.
	CancelPurchaseOrder(context.Context, *CancelPurchaseOrderRequest) (*PurchaseOrder, error)
	// ClosePurchaseOrder moves a partially_received (short-close) or received
	// PO to closed. Any other source status is po_illegal_transition; exactly
	// one po.closed outbox event commits with the transition.
	ClosePurchaseOrder(context.Context, *ClosePurchaseOrderRequest) (*PurchaseOrder, error)
	// ListPurchaseOrders returns one page of the caller tenant's purchase
	// orders ordered by number descending (newest first). query matches a number
	// prefix (case-insensitive); status is one of the seven lifecycle values or
	// empty; the two combine. total is the number of matching rows across all
	// pages. Rows are header-only: items are always empty here — the detail
	// read owns them.
	ListPurchaseOrders(context.Context, *ListPurchaseOrdersRequest) (*ListPurchaseOrdersResponse, error)
	// GetPurchaseOrder returns one purchase order of the caller's tenant — the
	// detail read that owns the lines the list rows never carry, with each
	// line's id (receipt lines reference po_item ids since #37). Other tenants'
	// purchase orders are indistinguishable from missing ones.
	GetPurchaseOrder(context.Context, *GetPurchaseOrderRequest) (*PurchaseOrder, error)
	// PostGoodsReceipt records one goods receipt against an acknowledged or
	// partially_received PO (FR-07): each line advances the PO line's
	// cumulative qty_received, over-receipts are rejected with the
	// grn_over_receipt detail line, and the PO status follows the
	// post-receipt quantities — partially_received while lines are short,
	// received once every line reaches qty_ordered (a further partial receipt
	// on a partially_received PO is legal and leaves the status untouched).
	// The GRN number (GRN-%06d) is allocated per tenant inside the posting
	// transaction — a rejected receipt burns no number. Exactly one grn.posted
	// outbox event commits with every successful receipt.
	PostGoodsReceipt(context.Context, *PostGoodsReceiptRequest) (*PostGoodsReceiptResponse, error)
	// CreateInvoice records one vendor invoice against an acknowledged,
	// partially_received, or received PO of the caller's tenant (#39): the
	// vendor_id and currency are derived server-side from the locked PO
	// (never client input), total_cents is recomputed server-side from the
	// lines, and the cumulative over-billing guard rejects — strictly, no
	// tolerance at create (tolerance is the #40 match's concern) — any
	// invoice whose amount plus the PO's existing invoices would exceed
	// po.total_cents, with the inv_over_bill detail line. The number is the
	// vendor's own invoice number, unique per (tenant, vendor) — the same
	// number under a different vendor is a different invoice. The PO is
	// locked but never mutated, and no outbox event is written (the §14.6
	// catalog's invoice.* events belong to the #40 match). Attachments are
	// declared after creation through the documents service (the architecture
	// has no cross-service atomicity); the "attachment required" obligation
	// is enforced by the demo flow (#41/#40), not by this API.
	CreateInvoice(context.Context, *CreateInvoiceRequest) (*Invoice, error)
	// GetInvoice returns one invoice of the caller's tenant — the detail read
	// with the lines. Other tenants' invoices are indistinguishable from
	// missing ones. status stays pending until the #40 match moves it;
	// match_result_json carries the match's explanation once it ran (empty
	// while pending).
	GetInvoice(context.Context, *GetInvoiceRequest) (*Invoice, error)
	// MatchInvoice applies the three-way match (#40, FR-08) to one invoice of
	// the caller's tenant: every line's cumulative invoiced quantity (across
	// ALL the PO's invoices, this one included) is checked against the PO
	// line's received quantity — upper-side only, within the tenant's
	// qty_pct tolerance — and this invoice's unit price against the PO price,
	// symmetrically within price_pct. The verdict lands atomically with its
	// explanation: status moves pending/discrepancy → matched/discrepancy,
	// match_result_json fills with the per-line detail, and exactly one
	// invoice.matched or invoice.discrepancy outbox event commits with it.
	// Re-running on matched is rejected (409 inv_already_matched);
	// pending/discrepancy may be re-matched (a late GRN resolving a
	// discrepancy), each run appending its own event. No attachment gate —
	// the "attachment required" obligation stays with the demo flow (#41).
	MatchInvoice(context.Context, *MatchInvoiceRequest) (*Invoice, error)
	// GetMatchSettings returns the caller tenant's match tolerances; a tenant
	// with no stored row reads the effective defaults 0%/0% (strict).
	GetMatchSettings(context.Context, *GetMatchSettingsRequest) (*MatchSettings, error)
	// ReplaceMatchSettings upserts the caller tenant's match tolerances
	// (match:configure, admin-only). Values apply to match runs that start
	// after the commit; stored match results are immutable history.
	ReplaceMatchSettings(context.Context, *ReplaceMatchSettingsRequest) (*MatchSettings, error)
	mustEmbedUnimplementedProcurementServer()
}

